// Determine directory path safely in both ESM (dev) and CJS bundle (production)
const currentDir = typeof __dirname !== 'undefined' ? __dirname : process.cwd();

const app = express();
const PORT = Number(process.env.PORT) || 3000;

// Allowed origins for CORS (Local development, Android Capacitor apps, and optional custom domains)
const allowedOrigins = [
  'http://localhost',
  'http://localhost:5173',
  'http://localhost:3000',
  'https://localhost',
  'capacitor://localhost',
];

// Add custom frontend origin from environment variable if configured
if (process.env.ALLOWED_ORIGIN) {
  process.env.ALLOWED_ORIGIN.split(',').forEach((origin) => {
    const trimmed = origin.trim();
    if (trimmed && !allowedOrigins.includes(trimmed)) {
      allowedOrigins.push(trimmed);
    }
  });
}

// Flexible CORS middleware supporting Web and Mobile Capacitor clients
app.use(
  cors({
    origin: (origin, callback) => {
      // Allow requests with no origin (e.g. mobile apps, curl, server-to-server)
      if (!origin) return callback(null, true);
      if (allowedOrigins.includes(origin) || origin.endsWith('.run.app')) {
        return callback(null, true);
      }
      return callback(null, true); // Permissive for API routes while respecting headers
    },
    methods: ['GET', 'POST', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
    credentials: true,
  })
);

// Security: limit body size to prevent payload exhaustion (30MB)
app.use(express.json({ limit: '30mb' }));
app.use(express.urlencoded({ extended: true, limit: '30mb' }));

// Payload too large and JSON parsing error handling middleware
app.use((err: any, req: express.Request, res: express.Response, next: express.NextFunction) => {
  if (err.type === 'entity.too.large' || err.status === 413) {
    return res.status(413).json({
      success: false,
      status: 413,
      error: 'حجم الملف أو البيانات المرفقة يتجاوز الحد الأقصى المسموح به (30 ميغابايت). يرجى تقليل حجم الملف والمحاولة مجدداً.',
    });
  }
  if (err instanceof SyntaxError && 'body' in err) {
    return res.status(400).json({
      success: false,
      status: 400,
      error: 'صيغة الطلب أو البيانات المرسلة غير صالحة (Invalid JSON Payload).',
    });
  }
  next(err);
});

// --- Security Layer: In-Memory Sliding-Window Rate Limiter ---
interface RateLimitRecord {
  timestamps: number[];
}
const rateLimitMap = new Map<string, RateLimitRecord>();
const RATE_LIMIT_WINDOW_MS = 60 * 1000; // 1 minute
const MAX_REQUESTS_PER_WINDOW = 25; // 25 requests per minute

function rateLimiter(req: express.Request, res: express.Response, next: express.NextFunction) {
  const clientIp = (req.headers['x-forwarded-for'] as string) || req.socket.remoteAddress || 'unknown-client';
  const now = Date.now();

  const record = rateLimitMap.get(clientIp) || { timestamps: [] };
  // Filter out timestamps outside the current window
  const validTimestamps = record.timestamps.filter((ts) => now - ts < RATE_LIMIT_WINDOW_MS);

  if (validTimestamps.length >= MAX_REQUESTS_PER_WINDOW) {
    res.status(429).json({
      success: false,
      error: 'لقد تجاوزت الحد الأقصى المسموح به من الطلبات مؤقتاً. يرجى الانتظار دقيقة واحدة ثم المحاولة مرة أخرى.',
    });
    return;
  }

  validTimestamps.push(now);
  rateLimitMap.set(clientIp, { timestamps: validTimestamps });
  next();
}

// Clean up stale rate limit entries every 10 minutes
setInterval(() => {
  const now = Date.now();
  for (const [ip, record] of rateLimitMap.entries()) {
    const valid = record.timestamps.filter((ts) => now - ts < RATE_LIMIT_WINDOW_MS);
    if (valid.length === 0) {
      rateLimitMap.delete(ip);
    } else {
      rateLimitMap.set(ip, { timestamps: valid });
    }
  }
}, 10 * 60 * 1000);

// --- Security Layer: Sanitizer helper ---
function sanitizeInput(str: unknown): string {
  if (typeof str !== 'string') return '';
  return str
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
    .replace(/<[^>]+>/g, '')
    .replace(/javascript:/gi, '')
    .trim()
    .slice(0, 15000); // hard cap character length
}

// Lazy initializer for Gemini
function getGeminiClient(): GoogleGenAI {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) {
    throw new Error('GEMINI_API_KEY environment variable is missing.');
  }
  return new GoogleGenAI({
    apiKey,
    httpOptions: {
      headers: {
        'User-Agent': 'aistudio-build',
      },
    },
  });
}

